local function checkOwner(player)
    local ownerId = customGame:getOwnerId()
    if player.userId ~= ownerId then
        return false
    end
    return true
end

-- V1版本的APP请求房间设置。拿到的是 默认为member的设置
function PacketHandlers:syncCustomRoomSetting(packet)
    local player = PlayerManager:getPlayerByUserId(self.userId)
    if not player then 
        return 
    end
    local perm = TableUtil.copyTable(player.permissionSetting)
    if not customGame.isOldPermMgrGame then
        local gPerm = customGame:getGlobalPermSetting()
        for i, v in pairs(perm) do
            if gPerm[i] and gPerm[i] == false then
                perm[i]=false
            end
        end
    end
    self:sendPacket({
        pid = "syncCustomRoomSetting",
        data = perm
    })
end

function PacketHandlers:syncCustomRoomDisableChat(packet)
    local players = PlayerManager:getPlayers()
    local ids = {}
    for i, player in pairs(players) do
        if player.entityPlayerMP and player.entityPlayerMP:getBoolProperty("DisableChat") then
            table.insert(ids, player.userId)
        end
    end
    self:sendPacket({
        pid = "syncCustomRoomDisableChat",
        data = ids
    })
end

-- V1版本更新房间权限设置
function PacketHandlers:updateCustomRoomSetting(packet)
    if not checkOwner(self) then return  end

    local players = PlayerManager:getAllPlayer()
    for _, player in pairs(players) do
        for _, setting in pairs(packet.data) do
            player:updatePermission(setting.id, setting.switch)
        end
        player:notifyUpdatePermSettingv1()
    end

end


-- V2版本修改玩家权限信息
function PacketHandlers:updateUserPermissionSetting(packet)
    --print("updateUserPermissionSetting "..StringUtil.v2s(packet, 10))
    local fromUser = PlayerManager:getPlayerByUserId(self.userId)
    if not fromUser then 
        return 
    end

    local targetUser = PlayerManager:getPlayerByUserId(packet.data.userId)
    if not targetUser then
        return
    end
    
    -- 检查权限 - 房主能修改所有人的权限，管理员只能修改自己和管理员以下级别玩家的权限
    -- 非房主只能修改自己和权限比自己低的玩家
    if not checkOwner(self) and  fromUser:getPermissionRole() ~= Define.CustomGamePermissionRole.Admin then
        return
    end

    if fromUser:getPermissionRole() == Define.CustomGamePermissionRole.Admin then 
        if fromUser.userId ~= targetUser.userId and targetUser:getPermissionRole() <= fromUser:getPermissionRole() then
            return
        end
    end

    local info = packet.data
    local player = PlayerManager:getPlayerByUserId(info.userId)
    if player then 
        player:updatePermissionSetingList(fromUser.name, fromUser:getPermissionRole(), info.permissionType, info.settingList)
    end
end

