function PacketHandlers:exchangeOwner(packet)
    if customGame:getOwnerId() == self.userId then
        local oldOwnerPlayer = PlayerManager:getPlayerByUserId(customGame:getOwnerId())
        local newOwnerPlayer = PlayerManager:getPlayerByUserId(packet.data)
        customGame:exchangeOwner(oldOwnerPlayer, newOwnerPlayer)
    end
end

function PacketHandlers:onCustomRoomKickOut(packet)
    local result = 1
    local msg = ""
     if not checkOwner(self) then return  end

    local id = StringUtil.split(tostring(packet.id) or "", '"')
    local player = PlayerManager:getPlayerByUserId(tonumber(id[1] or packet.id))
    if not player then
        result = 0
        msg = "player.is.not.exist"
    end
    self:sendPacket({
        pid = "customRoomKickOutResult",
        data = {
            userId = tonumber(packet.id),
            code = result,
            msg = msg
        }
    })
    if result == 0 then
        return
    end
    HostApi.sendGameover(player.rakssid, IMessages:msgGameOver(), GameOverCode.GameOver)
end

function PacketHandlers:onCustomRoomSaveMap(packet)
    local data = packet.data
    if not checkOwner(self) then return end
    data.userId = self.userId

    if data.version == nil then
        data.version = 1
    end
    if data.iconUrl == nil then 
        data.iconUrl = ""
    end
    if data.mapId == nil then 
        data.mapId = "" -- 覆盖的时候才有值
    end
    if data.mapName == nil then 
        data.mapName = ""
    end
    if data.exitGame == nil then
        data.exitGame = true
    end
    if data.uploadWork == nil then
        data.uploadWork = false
    end
    data.maxPlayer = customGame:getMaxPlayer()
    local ugcExtraConfig = customGame:getUGCExtraConfig() or { buildSize = {} }
    data.primaryTag = ugcExtraConfig.primaryTag or ""
    data.secondaryTag = ugcExtraConfig.secondaryTag or ""
    data.editX = ugcExtraConfig.buildSize.x or 0
    data.editY = ugcExtraConfig.buildSize.y or 0
    data.editZ = ugcExtraConfig.buildSize.z or 0
    data.maxBlockCount = ugcExtraConfig.maxBlockCount or 0
    data.curBlockCount = ugcExtraConfig.blockNum or 0

    customGame:onCustomRoomSaveMap(data)
end

function PacketHandlers:onCustomRoomDisableChat(packet)
    local data = packet.data
    local result = 1
    local msg = ""

     if not checkOwner(self) then return  end

    local player = PlayerManager:getPlayerByUserId(tonumber(data.userId))
    if not player then
        result = 0
        msg = "player.is.not.exist"
    end
    self:sendPacket({
        pid = "customRoomDisableChatResult",
        data = {
            userId = tonumber(data.userId),
            code = result,
            msg = msg,
            muteType = data.muteType
        }
    })
    if result == 0 then
        return
    end
    local disable = tonumber(data.muteType)
    if disable == 1 then 
        player.entityPlayerMP:setBoolProperty("DisableChat", true)
    else
        player.entityPlayerMP:setBoolProperty("DisableChat", false)
    end
end


function PacketHandlers:requestAllPlayerPermSetting()
    local allPerm = {}
    allPerm.settingList = {}
    for id, value in pairs(customGame:getGlobalPermSetting(true)) do
        local perm = {}
        perm.id = id
        perm.displayTitle = "room_setting_"..id
        perm.switch = not value -- app传过来的是 禁止XX 的值。所以这里要取反
        if customGame.isOldPermMgrGame then  -- 旧版 全局保持跟当前一致
            perm.switch = not self.permissionSetting[id]
        end
        table.insert(allPerm.settingList, perm)
    end
    allPerm.playerSettingList = customGame:getAllPlayerPermSettingForApp()
    allPerm.defPermissionSettingList = customGame:getAllDefaultPermSetting()
    self:sendPacket({
        pid = "returnAllPlayerPermSetting",
        data = allPerm
    })
end

function PacketHandlers:CreativeAddItem(packet)
    local player = PlayerManager:getPlayerByUserId(self.userId)
    if not player then 
        return
    end
    
    if not player:getPermissionSetting(Define.CustomRoomSettingType.UNLIMIT_ITEM) then 
        return 
    end

    local itemId = packet.data.id
    local meta = packet.data.meta
    local itemCount = packet.data.count
    local ItemsConfig = T(Global, "ItemsConfig")
    if not ItemsConfig:checkGoodsInfoEnable(itemId, meta) then 
        return
    end

    if not self:checkCanAddItem(itemId, meta, itemCount) then
        PidPacketSender:sendShopTip(self.userId, "gui.shop.is.full.inventory")
        return
    end
    self:addItem(itemId, itemCount, meta)
end

