function PacketHandlers:selectTeamStatus(packet)
    if not checkOwner(self) then return  end
    self.isSelectTeam = packet.data.teamId
    if self.isSelectTeam > 0 then
        self.isSelectTeamType = packet.data.type
        self.entityPlayerMP:changeCurrentItem(0)
        local info = self.entityPlayerMP:getInventory():getItemStackInfo(0)
        self.stack0Item = {id = info.id, num = info.num}
        local itemId = 0
        local meta = 0
        if packet.data.type == Define.SelectTeam.Position then
            itemId = Define.TeamFlagItem[self.isSelectTeam] or Define.TeamFlagItem[1]
        else
            itemId = ItemID.BED -- packet.data.itemId or 1
            meta = 0 -- packet.data.meta or 0
        end
        self:replaceItem(itemId, 1, meta, 0)
    else
        self.isSelectTeamType = nil
        if self.stack0Item then
            self:replaceItem(self.stack0Item.id, self.stack0Item.num, nil, 0)
        else
            self:removeItem(itemId, 1)
        end
    end
end

